import {read,put,makeId} from './project-store.js';
const node=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
export async function brandKits(){const value=await read('brand-kits');if(Array.isArray(value))return value;const old=await read('brand-kit');return old?[{...old,id:makeId()}]:[]}
export async function activeBrand(){const kits=await brandKits(),id=await read('active-brand-kit');return kits.find(k=>k.id===id)||kits[0]||null}
export async function renderBrandKits(root,{allowed=()=>true}={}){
 let kits=await brandKits(),current=(await activeBrand())?.id||'',logo='';
 const h=node('div','section-title');h.append(node('div','','Бренд-киты'));const create=node('button','ws-primary','+ Новый бренд-кит');create.type='button';h.append(create);root.append(node('h1','','Бренд-киты'),node('p','ai-settings-lead','Отдельные логотипы, цвета и подписи для каждого проекта. Хранятся в этом браузере, внутри вашего аккаунта.'),h);
 const tabs=node('div','brand-kit-list'),form=node('form','brand-form');root.append(tabs,form);
 const fresh=()=>({id:makeId(),brandName:'',tagline:'',accent:'#ffffff',textColor:'#f8f8f8',background:'#101010',tone:'Спокойный и уверенный',logo:''});let draft=kits.find(k=>k.id===current)||fresh();
 function draw(){tabs.replaceChildren();for(const k of kits){const b=node('button',k.id===current?'ws-primary':'ws-outline',k.brandName||'Без названия');b.type='button';b.onclick=()=>{current=k.id;draft={...k};draw()};tabs.append(b)}form.innerHTML='<div class="ws-card"><h2>Основы бренда</h2><label>Название<input name="brandName" maxlength="70" required placeholder="Название бренда"></label><label>Подпись<input name="tagline" maxlength="100" placeholder="Короткая фраза для финальной сцены"></label><label>Логотип<input name="logoFile" type="file" accept="image/png,image/jpeg,image/webp"></label><small>PNG, JPEG или WebP, до 1 МБ. Прозрачный PNG подходит лучше.</small><button type="button" class="ws-text-link" data-remove-logo>Убрать логотип</button><div class="ws-form-row"><label>Акцент<input name="accent" type="color"></label><label>Текст<input name="textColor" type="color"></label><label>Фон<input name="background" type="color"></label></div><label>Тон<select name="tone"><option>Спокойный и уверенный</option><option>Энергичный и смелый</option><option>Дружелюбный и простой</option><option>Экспертный и точный</option></select></label><div class="brand-kit-actions"><button class="ws-primary" type="submit">Сохранить и использовать</button><button type="button" class="ws-outline" data-duplicate>Дублировать</button><button type="button" class="ws-text-link" data-delete>Удалить набор</button></div><p class="brand-status" role="status"></p></div><div class="brand-preview"><img class="brand-preview-logo" alt="Предпросмотр логотипа" hidden><span>Предпросмотр</span><h2></h2><p></p><div class="preview-colors"><i></i><i></i><i></i></div></div>';
 logo=draft.logo||'';for(const k of ['brandName','tagline','accent','textColor','background','tone'])form.elements[k].value=draft[k]||'';
 const status=s=>form.querySelector('.brand-status').textContent=s;
 const update=()=>{const p=form.querySelector('.brand-preview');p.style.background=form.elements.background.value;p.style.color=form.elements.textColor.value;p.querySelector('h2').textContent=form.elements.brandName.value||'Название бренда';p.querySelector('p').textContent=form.elements.tagline.value||'Ваша подпись';const image=p.querySelector('img');image.hidden=!logo;if(logo)image.src=logo;else image.removeAttribute('src');p.querySelectorAll('i').forEach((n,i)=>n.style.background=form.elements[['accent','textColor','background'][i]].value)};form.oninput=update;update();
 form.elements.logoFile.onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1048576){status('Выберите PNG, JPEG или WebP до 1 МБ.');e.target.value='';return}try{const bmp=await createImageBitmap(file);if(bmp.width>4096||bmp.height>4096)throw Error('Максимальный размер — 4096 × 4096.');bmp.close();logo=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});update();status('Логотип загружен. Сохраните набор.')}catch(err){status(err.message||'Изображение повреждено')}};
 form.querySelector('[data-remove-logo]').onclick=()=>{logo='';update()};
 form.querySelector('[data-duplicate]').onclick=()=>{draft={...Object.fromEntries(new FormData(form)),id:makeId(),logo,brandName:form.elements.brandName.value+' — копия'};current=draft.id;draw()};
 form.querySelector('[data-delete]').onclick=async()=>{if(!kits.some(k=>k.id===draft.id))return;if(!confirm('Удалить этот бренд-кит? Уже применённые сцены сохранят оформление.'))return;kits=kits.filter(k=>k.id!==draft.id);await put('brand-kits',kits);current=kits[0]?.id||'';await put('active-brand-kit',current);draft=kits[0]||fresh();draw()};
 form.onsubmit=async e=>{e.preventDefault();if(!allowed())return;try{if(kits.length>=20&&!kits.some(k=>k.id===draft.id))throw Error('Максимум 20 наборов. Удалите ненужный.');const saved={id:draft.id,logo};for(const k of ['brandName','tagline','accent','textColor','background','tone'])saved[k]=form.elements[k].value;kits=[...kits.filter(k=>k.id!==saved.id),saved];await put('brand-kits',kits);await put('active-brand-kit',saved.id);await put('brand-kit',saved);draft=saved;current=saved.id;draw();status('Сохранено. Этот набор выбран для применения в редакторе.')}catch(err){status(err.message)}};
 }
 create.onclick=()=>{draft=fresh();current=draft.id;draw();form.elements.brandName.focus()};draw();
}
